For future readers: to enable crossOriginIsolation and SharedArrayBuffer also in workers I had to also force some configurations

```ts
import type { LaunchOptions, PlaywrightTestConfig } from "@playwright/test";
import { defineConfig, devices } from "@playwright/test";
import { baseURL } from "./constants";

import "dotenv/config";
import { isCI, isDebug, withCrossOriginIsolation } from "./env";

import type { TestOptions } from "./fixtures";

const serveCommand = withCrossOriginIsolation() ? "npm run serve" : "npm run serve-no-cross-origin-isolated";

const commonLaunchOptions: LaunchOptions = {
  devtools: isDebug(),
  slowMo: isDebug() ? 1000 : 0,
};

// Base launch options that are always needed
const commonLaunchOptionsArgs: LaunchOptions["args"] = [
  "--allow-file-access-from-files",
  "--disable-translate",
  "--mute-audio",
  "--use-fake-device-for-media-stream",
  "--use-fake-ui-for-media-stream",
  "--disable-dev-shm-usage",
];

// Add SharedArrayBuffer specific args only when needed
if (isWebAssemblyPthreadsBuild()) {
  commonLaunchOptionsArgs.push(
    "--enable-features=SharedArrayBuffer",
    "--disable-site-isolation-trials"
  );
}

const headless = !isCI();
const ignoreHTTPSErrors = true;
const bypassCSP = true;
let workers = undefined;

if (isCI() && withCrossOriginIsolation()) {
  workers = 1;
} else if (isCI()) {
  workers = 3;
}

const config: PlaywrightTestConfig<TestOptions> = {
  testDir: "./modules",
  retries: isCI() ? 4 : 0,
  workers: workers,
  fullyParallel: true,
  forbidOnly: isCI(),
  timeout: 60000,
  expect: {
    timeout: 10000,
  },
  reporter: [["list"], isCI() ? ["blob"] : ["html", { open: "always" }]],
  projects: [
    {
      name: "chromium",
      use: {
        headless,
        ignoreHTTPSErrors,
        bypassCSP,
        ...devices["Pixel 7"],
        launchOptions: {
          args: [...commonLaunchOptionsArgs],
          ...commonLaunchOptions,
        },
      },
    },
  ],
  webServer: {
    command: serveCommand,
    port: Number.parseInt(new URL(baseURL).port, 10),
    reuseExistingServer: !isCI(),
  },
  use: {
    trace: "on-first-retry",
    baseURL,
  },
};

// when emulating firefox seems we cannot
// redefine getUserMedia function
const fireFoxDevice = {
  ...devices["Desktop Firefox"],
  userAgent: devices["Pixel 7"].userAgent,
  viewport: {
    ...devices["Pixel 7"].viewport,
  },
};

config.projects?.push({
  name: "firefox",
  use: {
    headless,
    ignoreHTTPSErrors,
    bypassCSP,
    ...fireFoxDevice,
    launchOptions: {
      firefoxUserPrefs: {
        "media.navigator.streams.fake": true,
        "media.navigator.permission.disabled": true,
        "javascript.options.shared_memory": isWebAssemblyPthreadsBuild(),
        "dom.postMessage.sharedArrayBuffer.bypassCOOP_COEP.insecure.enabled": isWebAssemblyPthreadsBuild()
      },
      ...commonLaunchOptions,
    },
  },
});

config.projects?.push({
  name: "webkit",
  use: {
    headless,
    ignoreHTTPSErrors,
    bypassCSP,
    ...devices["iPhone 13"],
    ...(isWebAssemblyPthreadsBuild() && {
      launchOptions: {
        args: ['--enable-features=SharedArrayBuffer'],
      },
      contextOptions: {
        serviceWorkers: 'block'
      }
    })
  },
});

export default defineConfig(config);
```

